import {type DefaultError, useMutation} from '@github-ui/react-query'
import {reactFetch} from '@github-ui/verified-fetch'
import {commitMutation, type Environment, graphql} from 'react-relay'

import type {IssueType} from '../types/issue-type'
import type {IssueTypeColor} from './__generated__/createIssueTypeMutation.graphql'
import type {
  UpdateIssueTypeInput,
  updateIssueTypeMutation,
  updateIssueTypeMutation$data,
} from './__generated__/updateIssueTypeMutation.graphql'

type UpdateIssueTypeMutationParams = {
  environment: Environment
  input: UpdateIssueTypeInput
  onError?: (error: Error) => void
  onCompleted?: (response: updateIssueTypeMutation$data) => void
}

export type UpdateIssueTypeMutationInput = {
  issueTypeId: string
  name?: string
  color?: IssueTypeColor
  description?: string
  isEnabled?: boolean
  pinnedIssueFieldIds?: string[]
}

export type UpdateIssueTypeMutationResult = IssueType | {errors: string[]}

export function useUpdateIssueTypeMutation({
  owner,
  onError,
  onSuccess,
}: {
  owner: string
  onError: (error: Error, variables: UpdateIssueTypeMutationInput) => void
  onSuccess: (data: UpdateIssueTypeMutationResult, variables: UpdateIssueTypeMutationInput) => void
}) {
  return useMutation<UpdateIssueTypeMutationResult, DefaultError, UpdateIssueTypeMutationInput>({
    onError,
    onSuccess,
    mutationFn: async (payload: UpdateIssueTypeMutationInput) => {
      const {issueTypeId, name, description, isEnabled, color, pinnedIssueFieldIds} = payload
      const pathname = `/organizations/${owner}/settings/issue-types/${issueTypeId}`

      const formData = new FormData()
      formData.append('id', issueTypeId)
      if (name) {
        formData.append('name', name)
      }
      if (isEnabled !== undefined) {
        formData.append('is_enabled', isEnabled.toString())
      }
      if (description) {
        formData.append('description', description)
      }
      if (color) {
        formData.append('color', color)
      }
      if (pinnedIssueFieldIds) {
        formData.append('pinned_issue_field_ids', JSON.stringify(pinnedIssueFieldIds))
      }

      const response = await reactFetch(pathname, {
        method: 'PATCH',
        body: formData,
      })

      return (await response.json()) as UpdateIssueTypeMutationResult
    },
  })
}

export function commitUpdateIssueTypeMutation({
  environment,
  input,
  onError,
  onCompleted,
}: UpdateIssueTypeMutationParams) {
  return commitMutation<updateIssueTypeMutation>(environment, {
    mutation: graphql`
      mutation updateIssueTypeMutation($input: UpdateIssueTypeInput!) @raw_response_type {
        updateIssueType(input: $input) {
          issueType {
            id
            # eslint-disable-next-line relay/unused-fields
            name
            # eslint-disable-next-line relay/unused-fields
            isEnabled
            # eslint-disable-next-line relay/unused-fields
            description
            # eslint-disable-next-line relay/unused-fields
            color
          }
          errors {
            message
          }
        }
      }
    `,
    variables: {input},
    onError: error => onError && onError(error),
    onCompleted: response => onCompleted && onCompleted(response),
  })
}
