import {type DefaultError, useMutation} from '@github-ui/react-query'
import {reactFetch} from '@github-ui/verified-fetch'
import {commitMutation, ConnectionHandler, type Environment, graphql} from 'react-relay'

import type {IssueType} from '../types/issue-type'
import type {
  DeleteIssueTypeInput,
  deleteIssueTypeMutation,
  deleteIssueTypeMutation$data,
} from './__generated__/deleteIssueTypeMutation.graphql'

type deleteIssueTypeMutationParams = {
  environment: Environment
  input: DeleteIssueTypeInput
  connectionId?: string
  onError?: (error: Error) => void
  onCompleted?: (response: deleteIssueTypeMutation$data) => void
}

export type DeleteIssueTypeMutationResult = IssueType | {errors: string[]}

export function useDeleteIssueTypeMutation({
  owner,
  onError,
  onSuccess,
}: {
  owner: string
  onError: (error: Error) => void
  onSuccess: (data: DeleteIssueTypeMutationResult) => void
}) {
  return useMutation<DeleteIssueTypeMutationResult, DefaultError, DeleteIssueTypeInput>({
    onError,
    onSuccess,
    mutationFn: async (payload: DeleteIssueTypeInput) => {
      const {issueTypeId} = payload
      const pathname = `/organizations/${owner}/settings/issue-types/${issueTypeId}`

      const formData = new FormData()
      formData.append('id', issueTypeId)

      const response = await reactFetch(pathname, {
        method: 'DELETE',
        body: formData,
      })

      return (await response.json()) as DeleteIssueTypeMutationResult
    },
  })
}

export function commitDeleteIssueTypeMutation({
  environment,
  input,
  connectionId,
  onError,
  onCompleted,
}: deleteIssueTypeMutationParams) {
  return commitMutation<deleteIssueTypeMutation>(environment, {
    mutation: graphql`
      mutation deleteIssueTypeMutation($input: DeleteIssueTypeInput!) @raw_response_type {
        deleteIssueType(input: $input) {
          deletedIssueTypeId
          errors {
            message
          }
        }
      }
    `,
    variables: {input},
    updater: store => {
      if (!connectionId) return
      const deletedIssueTypeId = store.getRootField('deleteIssueType')?.getValue('deletedIssueTypeId')
      const connection = store.get(connectionId)

      if (connection && deletedIssueTypeId) {
        ConnectionHandler.deleteNode(connection, deletedIssueTypeId)

        const currentCount = connection.getValue('totalCount')
        if (typeof currentCount === 'number') {
          connection.setValue(currentCount - 1, 'totalCount')
        }

        store.delete(deletedIssueTypeId)
      }
    },
    onError: error => onError && onError(error),
    onCompleted: response => onCompleted && onCompleted(response),
  })
}
