import {registerDataRouterApp, registerNavigatorApp} from '@github-ui/react-core/register-app'
import {relayEnvironmentWithMissingFieldHandlerForNode} from '@github-ui/relay-environment'
import {relayRoute} from '@github-ui/relay-route'

import {App} from './App'
import {issueTypesSettingsAppBuilder} from './config/app-builder'
import {ORGANIZATION_ISSUE_TYPES_LIMIT} from './constants/constants'
import ORGANIZATION_ISSUE_TYPES_SETTINGS_CREATE_QUERY from './routes/__generated__/OrganizationIssueTypesSettingsCreateQuery.graphql'
import ORGANIZATION_ISSUE_TYPES_SETTINGS_EDIT_QUERY from './routes/__generated__/OrganizationIssueTypesSettingsEditQuery.graphql'
import ORGANIZATION_TYPE_SETTINGS_QUERY from './routes/__generated__/OrganizationIssueTypesSettingsQuery.graphql'
import {issueTypesSettingsEditRoute} from './routes/edit-route'
import {EditPage} from './routes/EditPage'
import {issueTypesSettingsIndexRoute} from './routes/index-route'
import {IndexPage} from './routes/IndexPage'
import {issueTypesSettingsNewRoute} from './routes/new-route'
import {NewPage} from './routes/NewPage'
import {OrganizationIssueTypesSettingsRelay} from './routes/OrganizationIssueTypesSettings'
import {OrganizationIssueTypesSettingsCreateRelay} from './routes/OrganizationIssueTypesSettingsCreate'
import {OrganizationIssueTypesSettingsEditRelay} from './routes/OrganizationIssueTypesSettingsEdit'

export const issueTypesSettingsApp = issueTypesSettingsAppBuilder.createDataRouterAppFromRoutes([
  issueTypesSettingsIndexRoute.toRoute({Component: IndexPage}),
  issueTypesSettingsNewRoute.toRoute({Component: NewPage}),
  issueTypesSettingsEditRoute.toRoute({Component: EditPage}),
])
registerDataRouterApp(issueTypesSettingsApp)

registerNavigatorApp('issue-types', () => {
  const relayEnvironment = relayEnvironmentWithMissingFieldHandlerForNode()
  return {
    App,
    routes: [
      relayRoute({
        path: '/organizations/:organization_id/settings/issue-types',
        resourceName: 'OrganizationIssueTypeSettings',
        title: 'Organization Issue Type settings',
        fallback: 'Loading...',
        componentLoader: async () => {
          throw new Error('This method should not be called')
        },
        Component: OrganizationIssueTypesSettingsRelay,
        relayEnvironment,
        queryConfigs: {
          organizationIssueTypesSettingsQuery: {
            concreteRequest: ORGANIZATION_TYPE_SETTINGS_QUERY,
            variableMappers: routeParams => {
              return {
                organization_id: routeParams.pathParams['organization_id'],
                pageSize: ORGANIZATION_ISSUE_TYPES_LIMIT,
              }
            },
          },
        },
      }),
      relayRoute({
        path: '/organizations/:organization_id/settings/issue-types/new',
        resourceName: 'OrganizationIssueTypesSettingsCreate',
        title: 'Create a new Issue Type',
        fallback: 'Loading...',
        componentLoader: async () => {
          throw new Error('This method should not be called')
        },
        Component: OrganizationIssueTypesSettingsCreateRelay,
        relayEnvironment,
        queryConfigs: {
          organizationIssueTypesSettingsCreateQuery: {
            concreteRequest: ORGANIZATION_ISSUE_TYPES_SETTINGS_CREATE_QUERY,
            variableMappers: routeParams => {
              return {
                organization_id: routeParams.pathParams['organization_id'],
              }
            },
          },
        },
      }),
      relayRoute({
        path: '/organizations/:organization_id/settings/issue-types/:id',
        resourceName: 'OrganizationIssueTypesSettingsEdit',
        title: 'Edit Issue Type',
        fallback: 'Loading...',
        componentLoader: async () => {
          throw new Error('This method should not be called')
        },
        Component: OrganizationIssueTypesSettingsEditRelay,
        relayEnvironment,
        queryConfigs: {
          organizationIssueTypesSettingsEditQuery: {
            concreteRequest: ORGANIZATION_ISSUE_TYPES_SETTINGS_EDIT_QUERY,
            variableMappers: routeParams => {
              return {
                organization_id: routeParams.pathParams['organization_id'],
                id: routeParams.pathParams['id'],
              }
            },
          },
        },
      }),
    ],
  }
})
