import {isFeatureEnabled} from '@github-ui/feature-flags'
import {useQueryClient} from '@github-ui/react-query'
import {ssrSafeWindow} from '@github-ui/ssr-utils'
import {useCallback} from 'react'
import {ConnectionHandler, useRelayEnvironment} from 'react-relay'

import {Resources} from '../constants/strings'
import {useIssueTypesMutationErrorsContext} from '../contexts/IssueTypesMutationErrorsContext'
import {
  commitDeleteIssueTypeMutation,
  type DeleteIssueTypeMutationResult,
  useDeleteIssueTypeMutation,
} from '../mutations/delete-issue-type-mutation'
import {formatError} from '../utils'

export const useDeleteIssueType = (owner: string, onDone?: () => void, redirect = true) => {
  const environment = useRelayEnvironment()
  const {setMutationError, clearError} = useIssueTypesMutationErrorsContext()
  const useRelay = !isFeatureEnabled('issue_types_settings_data_router')

  // this is safe because the feature flag cannot change during the lifetime of the react app
  // eslint-disable-next-line react-hooks/react-compiler
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const queryClient = !useRelay ? useQueryClient() : null

  const deleteIssueTypeMutation = !useRelay
    ? // this is safe because the feature flag cannot change during the lifetime of the react app
      // eslint-disable-next-line react-hooks/react-compiler
      // eslint-disable-next-line react-hooks/rules-of-hooks
      useDeleteIssueTypeMutation({
        owner,
        onError: () => {
          setMutationError(Resources.deletedIssueTypeError)
          onDone?.()
        },
        onSuccess: (data: DeleteIssueTypeMutationResult) => {
          if ('errors' in data) {
            data.errors.map(e => reportError(formatError('DeleteIssueType', e)))
            setMutationError(Resources.deletedIssueTypeError)
          } else {
            if (redirect && ssrSafeWindow) {
              ssrSafeWindow.location.href = `/organizations/${owner}/settings/issue-types`
            }
          }
        },
      })
    : null

  const deleteIssueType = useCallback(
    async (issueTypeId: string, organizationId?: string) => {
      clearError()

      if (useRelay) {
        const connectionId = organizationId
          ? ConnectionHandler.getConnectionID(organizationId, 'Organization_issueTypes')
          : undefined

        commitDeleteIssueTypeMutation({
          environment,
          input: {issueTypeId},
          connectionId,
          onError: () => {
            setMutationError(Resources.deletedIssueTypeError)
            onDone?.()
          },
          onCompleted: response => {
            const errors = response.deleteIssueType?.errors || []
            if (errors.length === 0) {
              if (redirect && ssrSafeWindow)
                ssrSafeWindow.location.href = `/organizations/${owner}/settings/issue-types`
            } else {
              errors.map((e: {message: string}) => reportError(formatError('DeleteIssueType', e.message)))
              setMutationError(Resources.deletedIssueTypeError)
            }
            onDone?.()
          },
        })
      } else {
        if (deleteIssueTypeMutation && queryClient) {
          await deleteIssueTypeMutation.mutateAsync({
            issueTypeId,
          })
        }
      }
    },
    [
      clearError,
      useRelay,
      environment,
      setMutationError,
      onDone,
      redirect,
      owner,
      deleteIssueTypeMutation,
      queryClient,
    ],
  )

  return {
    deleteIssueType,
  }
}
