import {isFeatureEnabled} from '@github-ui/feature-flags'
import {useQueryClient} from '@github-ui/react-query'
import {useCallback} from 'react'
import {useRelayEnvironment} from 'react-relay'

import {appName} from '../config/app-builder'
import {Resources} from '../constants/strings'
import {useIssueTypesMutationErrorsContext} from '../contexts/IssueTypesMutationErrorsContext'
import type {UpdateIssueTypeInput} from '../mutations/__generated__/updateIssueTypeMutation.graphql'
import {
  commitUpdateIssueTypeMutation,
  type UpdateIssueTypeMutationResult,
  useUpdateIssueTypeMutation,
} from '../mutations/update-issue-type-mutation'
import {issueTypesSettingsEditRouteId} from '../routes/edit-route'
import {issueTypesSettingsIndexRouteId} from '../routes/index-route'
import {formatError} from '../utils'

export const useEnableDisableIssueType = (owner: string, onDone?: () => void) => {
  const environment = useRelayEnvironment()
  const {setMutationError, clearError} = useIssueTypesMutationErrorsContext()
  const useRelay = !isFeatureEnabled('issue_types_settings_data_router')

  // this is safe because the feature flag cannot change during the lifetime of the react app
  // eslint-disable-next-line react-hooks/react-compiler
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const queryClient = !useRelay ? useQueryClient() : null

  const editMutation = !useRelay
    ? // this is safe because the feature flag cannot change during the lifetime of the react app
      // eslint-disable-next-line react-hooks/react-compiler
      // eslint-disable-next-line react-hooks/rules-of-hooks
      useUpdateIssueTypeMutation({
        owner,
        onSuccess: (result: UpdateIssueTypeMutationResult, variables: UpdateIssueTypeInput) => {
          if ('errors' in result) {
            const errors = result.errors || []
            if (errors.length > 0) {
              errors.map(e => reportError(formatError('UpdateIssueType', e)))
              const errorMessage = variables.isEnabled
                ? Resources.enabledIssueTypeError
                : Resources.disabledIssueTypeError
              setMutationError(errorMessage)
              onDone?.()
            }
          }
        },
        onError: (error: Error, variables: UpdateIssueTypeInput) => {
          const errorMessage = variables.isEnabled ? Resources.enabledIssueTypeError : Resources.disabledIssueTypeError
          setMutationError(errorMessage)
          onDone?.()
        },
      })
    : null

  const updateIssueType = useCallback(
    async (issueTypeId: string, isEnabled: boolean) => {
      clearError()
      if (useRelay) {
        commitUpdateIssueTypeMutation({
          environment,
          input: {
            issueTypeId,
            isEnabled,
          },
          onError: () => {
            const errorMessage = isEnabled ? Resources.enabledIssueTypeError : Resources.disabledIssueTypeError
            setMutationError(errorMessage)
            onDone?.()
          },
          onCompleted: response => {
            const errors = response.updateIssueType?.errors || []
            if (errors.length > 0) {
              errors.map((e: {message: string}) => reportError(formatError('UpdateIssueType', e.message)))
              const errorMessage = isEnabled ? Resources.enabledIssueTypeError : Resources.disabledIssueTypeError
              setMutationError(errorMessage)
            }
            onDone?.()
          },
        })
      } else {
        if (editMutation && queryClient) {
          await editMutation.mutateAsync({
            issueTypeId,
            isEnabled,
          })

          queryClient.invalidateQueries({queryKey: [appName, issueTypesSettingsIndexRouteId]})
          queryClient.invalidateQueries({queryKey: [appName, issueTypesSettingsEditRouteId]})
        }
      }
    },
    [clearError, editMutation, environment, onDone, queryClient, setMutationError, useRelay],
  )

  const enableOrganizationIssueType = (issueTypeId: string) => {
    updateIssueType(issueTypeId, true)
  }

  const disableOrganizationIssueType = (issueTypeId: string) => {
    updateIssueType(issueTypeId, false)
  }

  return {
    enableOrganizationIssueType,
    disableOrganizationIssueType,
  }
}
